-- Дамп структуры для таблица crp.bizstatistics
CREATE TABLE IF NOT EXISTS `bizstatistics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bizId` int(11) NOT NULL,
  `date` datetime NOT NULL,
  `money` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `bizstatistics_ibfk_1` (`bizId`),
  CONSTRAINT `bizstatistics_ibfk_1` FOREIGN KEY (`bizId`) REFERENCES `bizs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

