-- Дамп структуры для таблица crp.carlists
CREATE TABLE IF NOT EXISTS `carlists` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `carShowId` int(11) NOT NULL,
  `vehiclePropertyModel` varchar(128) NOT NULL,
  `percentage` int(11) NOT NULL DEFAULT '1',
  `count` int(11) NOT NULL DEFAULT '10',
  PRIMARY KEY (`id`),
  KEY `carShowId` (`carShowId`),
  KEY `vehiclePropertyModel` (`vehiclePropertyModel`),
  CONSTRAINT `carlists_ibfk_1` FOREIGN KEY (`carShowId`) REFERENCES `carshows` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `carlists_ibfk_2` FOREIGN KEY (`vehiclePropertyModel`) REFERENCES `vehicleproperties` (`model`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8;

