-- Дамп структуры для таблица crp.carservices
CREATE TABLE IF NOT EXISTS `carservices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bizId` int(11) DEFAULT NULL,
  `x` float NOT NULL DEFAULT '100',
  `y` float NOT NULL DEFAULT '100',
  `z` float NOT NULL DEFAULT '100',
  `radius` float NOT NULL DEFAULT '10',
  `priceMultiplier` float NOT NULL DEFAULT '1',
  `salaryMultiplier` float NOT NULL DEFAULT '0.1',
  PRIMARY KEY (`id`),
  KEY `carservices_ibfk_1` (`bizId`),
  CONSTRAINT `carservices_ibfk_1` FOREIGN KEY (`bizId`) REFERENCES `bizs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;

