  `cameraZ` float NOT NULL DEFAULT '100',
  `toX` float NOT NULL DEFAULT '100',
  `toY` float NOT NULL DEFAULT '100',
  `toZ` float NOT NULL DEFAULT '100',
  `toH` float NOT NULL DEFAULT '100',
  `returnX` float NOT NULL DEFAULT '100',
  `returnY` float NOT NULL DEFAULT '100',
