-- Дамп структуры для таблица crp.characterinventories
CREATE TABLE IF NOT EXISTS `characterinventories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `playerId` int(11) DEFAULT NULL,
  `itemId` int(11) NOT NULL,
  `pocketIndex` int(11) DEFAULT NULL,
  `index` int(11) NOT NULL,
  `parentId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `playerId` (`playerId`),
  KEY `parentId` (`parentId`),
  KEY `characterinventories_ibfk_2` (`itemId`),
  CONSTRAINT `characterinventories_ibfk_1` FOREIGN KEY (`playerId`) REFERENCES `characters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `characterinventories_ibfk_2` FOREIGN KEY (`itemId`) REFERENCES `inventoryitems` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `characterinventories_ibfk_3` FOREIGN KEY (`parentId`) REFERENCES `characterinventories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

