-- Дамп структуры для таблица crp.characters
CREATE TABLE IF NOT EXISTS `characters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `accountId` int(11) NOT NULL,
  `name` varchar(50) NOT NULL,
  `job` int(11) DEFAULT NULL,
  `factionId` int(11) DEFAULT NULL,
  `factionRank` int(11) DEFAULT NULL,
  `cash` int(11) NOT NULL DEFAULT '0',
  `bank` int(11) NOT NULL DEFAULT '0',
  `pay` int(11) NOT NULL DEFAULT '0',
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  `h` float NOT NULL DEFAULT '0',
  `status` int(11) NOT NULL DEFAULT '0',
  `admin` int(11) NOT NULL DEFAULT '0',
  `warnDate` datetime DEFAULT NULL,
  `warnNumber` int(11) NOT NULL DEFAULT '0',
  `minutes` int(11) NOT NULL DEFAULT '0',
  `creationDate` datetime NOT NULL,
  `carLicense` tinyint(1) NOT NULL DEFAULT '0',
  `passengerLicense` tinyint(1) NOT NULL DEFAULT '0',
  `bikeLicense` tinyint(1) NOT NULL DEFAULT '0',
  `truckLicense` tinyint(1) NOT NULL DEFAULT '0',
  `airLicense` tinyint(1) NOT NULL DEFAULT '0',
  `boatLicense` tinyint(1) NOT NULL DEFAULT '0',
  `gunLicenseDate` datetime DEFAULT NULL,
  `medCardDate` datetime DEFAULT NULL,
  `gender` int(11) NOT NULL,
  `father` int(11) NOT NULL,
  `mother` int(11) NOT NULL,
  `similarity` int(11) NOT NULL,
  `skin` int(11) NOT NULL,
  `hair` int(11) NOT NULL,
  `hairColor` int(11) NOT NULL,
  `hairHighlightColor` int(11) NOT NULL,
  `eyebrowColor` int(11) NOT NULL,
  `beardColor` int(11) NOT NULL,
  `eyeColor` int(11) NOT NULL,
  `blushColor` int(11) NOT NULL,
  `lipstickColor` int(11) NOT NULL,
  `chestHairColor` int(11) NOT NULL,
  `health` int(11) NOT NULL DEFAULT '100',
  `satiety` float NOT NULL DEFAULT '100',
  `thirst` float NOT NULL DEFAULT '100',
  `narcotism` int(11) NOT NULL DEFAULT '0',
  `nicotine` int(11) NOT NULL DEFAULT '0',
  `craft` int(11) NOT NULL DEFAULT '0',
  `law` int(11) NOT NULL DEFAULT '0',
  `crimes` int(11) NOT NULL DEFAULT '0',
  `wanted` int(11) NOT NULL DEFAULT '0',
  `wantedCause` varchar(255) DEFAULT NULL,
  `arrestTime` int(11) NOT NULL DEFAULT '0',
  `arrestType` tinyint(1) NOT NULL DEFAULT '0',
  `muteTime` int(11) NOT NULL DEFAULT '0',
  `inviterId` int(11) DEFAULT NULL,
  `inviteCompleted` tinyint(1) NOT NULL DEFAULT '0',
  `lastWheelSpin` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `accountId` (`accountId`),
  KEY `job` (`job`),
  KEY `inviterId` (`inviterId`),
  KEY `characters_ibfk_3` (`factionId`),
  KEY `characters_ibfk_4` (`factionRank`),
  CONSTRAINT `characters_ibfk_1` FOREIGN KEY (`accountId`) REFERENCES `accounts` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `characters_ibfk_2` FOREIGN KEY (`job`) REFERENCES `jobs` (`id`),
  CONSTRAINT `characters_ibfk_3` FOREIGN KEY (`factionId`) REFERENCES `factions` (`id`),
  CONSTRAINT `characters_ibfk_4` FOREIGN KEY (`factionRank`) REFERENCES `factionranks` (`id`),
  CONSTRAINT `characters_ibfk_5` FOREIGN KEY (`inviterId`) REFERENCES `characters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

