  `spawn` int(11) NOT NULL DEFAULT '0',
  `chatTimestamp` tinyint(1) NOT NULL DEFAULT '0',
  `chatSize` tinyint(1) NOT NULL DEFAULT '1',
  `nicknames` tinyint(1) NOT NULL DEFAULT '1',
  `hudKeys` tinyint(1) NOT NULL DEFAULT '1',
  `ghetto` tinyint(1) NOT NULL DEFAULT '1',
  `walking` int(11) NOT NULL DEFAULT '0',
  `mood` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `characterId` (`characterId`),
  CONSTRAINT `charactersettings_ibfk_1` FOREIGN KEY (`characterId`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

