-- Дамп структуры для таблица crp.clothestops
CREATE TABLE IF NOT EXISTS `clothestops` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(30) NOT NULL,
  `variation` int(11) NOT NULL,
  `pockets` varchar(128) DEFAULT '0',
  `clime` varchar(20) NOT NULL,
  `price` int(11) NOT NULL,
  `textures` varchar(128) NOT NULL,
  `sex` tinyint(1) NOT NULL,
  `torso` int(11) NOT NULL,
  `undershirt` int(11) NOT NULL,
  `uTextures` varchar(128) NOT NULL DEFAULT '[0]',
  `class` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=515 DEFAULT CHARSET=utf8;

