-- Дамп структуры для таблица crp.clothingshops
CREATE TABLE IF NOT EXISTS `clothingshops` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bizId` int(11) DEFAULT NULL,
  `bType` int(11) NOT NULL DEFAULT '0',
  `class` int(11) NOT NULL DEFAULT '1',
  `x` float NOT NULL DEFAULT '100',
  `y` float NOT NULL DEFAULT '100',
  `z` float NOT NULL DEFAULT '100',
  `placeX` float NOT NULL DEFAULT '100',
  `placeY` float NOT NULL DEFAULT '100',
  `placeZ` float NOT NULL DEFAULT '100',
  `placeH` float NOT NULL DEFAULT '100',
  `cameraX` float NOT NULL DEFAULT '100',
  `cameraY` float NOT NULL DEFAULT '100',
  `cameraZ` float NOT NULL DEFAULT '100',
  `priceMultiplier` float NOT NULL DEFAULT '1',
  `npcX` float NOT NULL DEFAULT '100',
  `npcY` float NOT NULL DEFAULT '100',
  `npcZ` float NOT NULL DEFAULT '100',
  `npcH` float NOT NULL DEFAULT '100',
  PRIMARY KEY (`id`),
  KEY `clothingshops_ibfk_1` (`bizId`),
  CONSTRAINT `clothingshops_ibfk_1` FOREIGN KEY (`bizId`) REFERENCES `bizs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8;

