-- Дамп структуры для таблица crp.clubs
CREATE TABLE IF NOT EXISTS `clubs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bizId` int(11) DEFAULT NULL,
  `blip` int(11) NOT NULL,
  `alcoholPrice` int(11) NOT NULL DEFAULT '1',
  `enterX` float NOT NULL,
  `enterY` float NOT NULL,
  `enterZ` float NOT NULL,
  `enterH` float NOT NULL,
  `exitX` float NOT NULL,
  `exitY` float NOT NULL,
  `exitZ` float NOT NULL,
  `exitH` float NOT NULL,
  PRIMARY KEY (`id`),
  KEY `clubs_ibfk_1` (`bizId`),
  CONSTRAINT `clubs_ibfk_1` FOREIGN KEY (`bizId`) REFERENCES `bizs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

