-- Дамп структуры для таблица crp.factionclothesranks
CREATE TABLE IF NOT EXISTS `factionclothesranks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `factionId` int(11) NOT NULL,
  `clothesIndex` int(11) NOT NULL,
  `rank` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `factionclothesranks_ibfk_1` (`factionId`),
  CONSTRAINT `factionclothesranks_ibfk_1` FOREIGN KEY (`factionId`) REFERENCES `factions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8;

