-- Дамп структуры для таблица crp.factioninventories
CREATE TABLE IF NOT EXISTS `factioninventories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `playerId` int(11) NOT NULL,
  `itemId` int(11) NOT NULL,
  `pocketIndex` int(11) DEFAULT NULL,
  `index` int(11) NOT NULL,
  `parentId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `playerId` (`playerId`),
  KEY `parentId` (`parentId`),
  KEY `factioninventories_ibfk_2` (`itemId`),
  CONSTRAINT `factioninventories_ibfk_1` FOREIGN KEY (`playerId`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `factioninventories_ibfk_2` FOREIGN KEY (`itemId`) REFERENCES `inventoryitems` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `factioninventories_ibfk_3` FOREIGN KEY (`parentId`) REFERENCES `factioninventories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10000 DEFAULT CHARSET=utf8;

-- Дамп данных таблицы crp.factioninventories: ~0 rows (приблизительно)

-- Дамп структуры для таблица crp.factioninventoryparams
CREATE TABLE IF NOT EXISTS `factioninventoryparams` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `key` varchar(255) NOT NULL,
  `value` text NOT NULL,
  `itemId` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `itemId` (`itemId`),
  CONSTRAINT `factioninventoryparams_ibfk_1` FOREIGN KEY (`itemId`) REFERENCES `factioninventories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Дамп данных таблицы crp.factioninventoryparams: ~0 rows (приблизительно)

-- Дамп структуры для таблица crp.factionitemranks
CREATE TABLE IF NOT EXISTS `factionitemranks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `factionId` int(11) NOT NULL,
  `itemId` int(11) NOT NULL,
  `rank` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `factionitemranks_ibfk_1` (`factionId`),
  KEY `factionitemranks_ibfk_2` (`itemId`),
  CONSTRAINT `factionitemranks_ibfk_1` FOREIGN KEY (`factionId`) REFERENCES `factions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `factionitemranks_ibfk_2` FOREIGN KEY (`itemId`) REFERENCES `inventoryitems` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8;

