-- Дамп структуры для таблица crp.factions
CREATE TABLE IF NOT EXISTS `factions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(128) NOT NULL,
  `leader` int(11) DEFAULT NULL,
  `leaderName` varchar(50) DEFAULT '',
  `products` int(11) NOT NULL DEFAULT '0',
  `money` int(64) NOT NULL DEFAULT '10000',
  `maxProducts` int(11) NOT NULL DEFAULT '1000',
  `blip` int(11) DEFAULT NULL,
  `blipColor` int(11) NOT NULL DEFAULT '1',
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  `h` float NOT NULL,
  `wX` float NOT NULL DEFAULT '0',
  `wY` float NOT NULL DEFAULT '0',
  `wZ` float NOT NULL DEFAULT '0',
  `sX` float NOT NULL,
  `sY` float NOT NULL,
  `sZ` float NOT NULL,
  `ammo` int(11) NOT NULL DEFAULT '0',
  `maxAmmo` int(11) NOT NULL DEFAULT '1000',
  `medicines` int(11) NOT NULL DEFAULT '0',
  `maxMedicines` int(11) NOT NULL DEFAULT '1000',
  `cash` int(11) NOT NULL DEFAULT '0',
  `inviteRank` int(11) NOT NULL DEFAULT '10',
  `uvalRank` int(11) NOT NULL DEFAULT '10',
  `giveRankRank` int(11) NOT NULL DEFAULT '10',
  `ammoRank` int(11) NOT NULL DEFAULT '5',
  `wD` int(11) NOT NULL DEFAULT '0',
  `sD` int(11) NOT NULL,
  `hD` int(11) NOT NULL,
  `d` int(11) NOT NULL DEFAULT '0',
  `hX` float NOT NULL,
  `hY` float NOT NULL,
  `hZ` float NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8;

