-- Дамп структуры для таблица crp.farms
CREATE TABLE IF NOT EXISTS `farms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `grains` int(11) NOT NULL DEFAULT '0',
  `soils` int(11) NOT NULL DEFAULT '0',
  `productA` int(11) NOT NULL DEFAULT '0',
  `productB` int(11) NOT NULL DEFAULT '0',
  `productC` int(11) NOT NULL DEFAULT '0',
  `productAPrice` int(11) NOT NULL DEFAULT '10',
  `productBPrice` int(11) NOT NULL DEFAULT '10',
  `productCPrice` int(11) NOT NULL DEFAULT '10',
  `grainPrice` int(11) NOT NULL DEFAULT '5',
  `soilPrice` int(11) NOT NULL DEFAULT '5',
  `price` int(11) NOT NULL DEFAULT '2000000',
  `playerId` int(11) DEFAULT NULL,
  `balance` int(11) NOT NULL DEFAULT '0',
  `taxBalance` int(11) NOT NULL DEFAULT '1000',
  `pay` int(11) NOT NULL DEFAULT '8',
  `farmerPay` int(11) NOT NULL DEFAULT '50',
  `tractorPay` int(11) NOT NULL DEFAULT '70',
  `pilotPay` int(11) NOT NULL DEFAULT '100',
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  PRIMARY KEY (`id`),
  KEY `playerId` (`playerId`),
  CONSTRAINT `farms_ibfk_1` FOREIGN KEY (`playerId`) REFERENCES `characters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

