  `angle` int(11) NOT NULL,
  `carX` float NOT NULL,
  `carY` float NOT NULL,
  `carZ` float NOT NULL,
  `carAngle` int(11) NOT NULL,
  `holder` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `characterId` (`characterId`),
  KEY `interiorId` (`interiorId`),
  CONSTRAINT `houses_ibfk_1` FOREIGN KEY (`characterId`) REFERENCES `characters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `houses_ibfk_2` FOREIGN KEY (`interiorId`) REFERENCES `interiors` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8;

