-- Дамп структуры для таблица crp.interiors
CREATE TABLE IF NOT EXISTS `interiors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `garageId` int(11) DEFAULT NULL,
  `class` varchar(50) NOT NULL,
  `numRooms` int(11) NOT NULL,
  `rent` float NOT NULL,
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  `rotation` int(11) NOT NULL,
  `exitX` float NOT NULL,
  `exitY` float NOT NULL,
  `exitZ` float NOT NULL,
  `hX` float NOT NULL,
  `hY` float NOT NULL,
  `hZ` float NOT NULL,
  PRIMARY KEY (`id`),
  KEY `garageId` (`garageId`),
  CONSTRAINT `interiors_ibfk_1` FOREIGN KEY (`garageId`) REFERENCES `garages` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;

