-- Дамп структуры для таблица crp.jobskills
CREATE TABLE IF NOT EXISTS `jobskills` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `characterId` int(11) NOT NULL,
  `jobId` int(11) NOT NULL,
  `exp` float NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `characterId` (`characterId`),
  KEY `jobId` (`jobId`),
  CONSTRAINT `jobskills_ibfk_1` FOREIGN KEY (`characterId`) REFERENCES `characters` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `jobskills_ibfk_2` FOREIGN KEY (`jobId`) REFERENCES `jobs` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Дамп данных таблицы crp.jobskills: ~0 rows (приблизительно)

-- Дамп структуры для таблица crp.logs
CREATE TABLE IF NOT EXISTS `logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `characterId` int(11) DEFAULT NULL,
  `playerId` int(11) DEFAULT NULL,
  `text` varchar(256) NOT NULL,
  `module` varchar(50) DEFAULT NULL,
  `date` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `characterId` (`characterId`),
  CONSTRAINT `logs_ibfk_1` FOREIGN KEY (`characterId`) REFERENCES `characters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Дамп данных таблицы crp.logs: ~0 rows (приблизительно)

-- Дамп структуры для таблица crp.lossantoscustoms
