  `returnZ` float NOT NULL DEFAULT '100',
  `returnH` float NOT NULL DEFAULT '100',
  `priceMultiplier` float NOT NULL DEFAULT '1',
  `npcX` float NOT NULL DEFAULT '100',
  `npcY` float NOT NULL DEFAULT '100',
  `npcZ` float NOT NULL DEFAULT '100',
  `npcH` float NOT NULL DEFAULT '100',
  PRIMARY KEY (`id`),
  KEY `lossantoscustoms_ibfk_1` (`bizId`),
  CONSTRAINT `lossantoscustoms_ibfk_1` FOREIGN KEY (`bizId`) REFERENCES `bizs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
