-- Дамп структуры для таблица crp.vehicleinventories
CREATE TABLE IF NOT EXISTS `vehicleinventories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `vehicleId` int(11) NOT NULL,
  `itemId` int(11) NOT NULL,
  `pocketIndex` int(11) DEFAULT NULL,
  `index` int(11) NOT NULL,
  `parentId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicleId` (`vehicleId`),
  KEY `parentId` (`parentId`),
  KEY `vehicleinventories_ibfk_2` (`itemId`),
  CONSTRAINT `vehicleinventories_ibfk_1` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vehicleinventories_ibfk_2` FOREIGN KEY (`itemId`) REFERENCES `inventoryitems` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `vehicleinventories_ibfk_3` FOREIGN KEY (`parentId`) REFERENCES `vehicleinventories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10000 DEFAULT CHARSET=utf8;

