-- Дамп структуры для таблица crp.vehicletunings
CREATE TABLE IF NOT EXISTS `vehicletunings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `vehicleId` int(11) NOT NULL,
  `spoiler` int(11) NOT NULL DEFAULT '-1',
  `frontBumper` int(11) NOT NULL DEFAULT '-1',
  `rearBumper` int(11) NOT NULL DEFAULT '-1',
  `sideSkirt` int(11) NOT NULL DEFAULT '-1',
  `exhaust` int(11) NOT NULL DEFAULT '-1',
  `frame` int(11) NOT NULL DEFAULT '-1',
  `grille` int(11) NOT NULL DEFAULT '-1',
  `hood` int(11) NOT NULL DEFAULT '-1',
  `fender` int(11) NOT NULL DEFAULT '-1',
  `rightFender` int(11) NOT NULL DEFAULT '-1',
  `roof` int(11) NOT NULL DEFAULT '-1',
  `engineType` int(11) NOT NULL DEFAULT '-1',
  `brakeType` int(11) NOT NULL DEFAULT '-1',
  `transmissionType` int(11) NOT NULL DEFAULT '-1',
  `horn` int(11) NOT NULL DEFAULT '-1',
  `suspensionType` int(11) NOT NULL DEFAULT '-1',
  `armourType` int(11) NOT NULL DEFAULT '-1',
  `turbo` int(11) NOT NULL DEFAULT '-1',
  `xenon` int(11) NOT NULL DEFAULT '-1',
  `frontWheels` int(11) NOT NULL DEFAULT '-1',
  `backWheels` int(11) NOT NULL DEFAULT '-1',
  `plateHolder` int(11) NOT NULL DEFAULT '-1',
  `trimDesign` int(11) NOT NULL DEFAULT '-1',
  `ornament` int(11) NOT NULL DEFAULT '-1',
  `dialDesign` int(11) NOT NULL DEFAULT '-1',
  `steeringWheel` int(11) NOT NULL DEFAULT '-1',
  `shiftLever` int(11) NOT NULL DEFAULT '-1',
  `plaque` int(11) NOT NULL DEFAULT '-1',
  `hydraulics` int(11) NOT NULL DEFAULT '-1',
  `boost` int(11) NOT NULL DEFAULT '-1',
  `windowTint` int(11) NOT NULL DEFAULT '-1',
  `livery` int(11) NOT NULL DEFAULT '-1',
  `plate` int(11) NOT NULL DEFAULT '-1',
  `neon` int(11) NOT NULL DEFAULT '-1',
  PRIMARY KEY (`id`),
  KEY `vehicleId` (`vehicleId`),
  CONSTRAINT `vehicletunings_ibfk_1` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

